insert into public.questions
(exam_category, subject, topic, type, difficulty, body, question_data, options, marks_correct, marks_wrong, explanation, concept_group_id, source_type, source_citation, status)
values
('upsc','History','Ancient','statement_based','hard','Consider the following statements regarding the decline of the Mauryan Empire:','{"statements": ["After Ashoka''s death, the Mauryan Empire began to decline, with some accounts suggesting a partition of the empire among his successors, including Dasaratha and Samprati.", "The last Mauryan ruler, Brihadratha, was assassinated by his own commander-in-chief, Pushyamitra Shunga, who then founded the Shunga dynasty.", "Pushyamitra Shunga is regarded, without dispute among ancient and modern historians, as a devout patron of Buddhism who continued Ashoka''s Dhamma policy without interruption."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the empire weakened and reportedly fragmented among Ashoka''s successors, and Brihadratha, the last Mauryan, was killed by Pushyamitra Shunga, who founded the Shunga dynasty. Statement 3 is incorrect: Pushyamitra Shunga is traditionally associated with a Brahmanical revival, and some Buddhist sources (such as the Divyavadana) even allege hostility toward Buddhism under his rule -- the claim of undisputed, uninterrupted continuation of Ashoka''s Dhamma policy does not hold.','ancient-mauryan-decline-shunga','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the decline of the Mauryan Empire and the rise of the Shungas.','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements regarding Kushan-era art schools:','{"statements": ["The Gandhara school of art, which flourished under Kushan patronage, shows strong Hellenistic/Greco-Roman influence in its depiction of the Buddha.", "The Mathura school of art developed largely indigenously and is generally considered to show more native Indian stylistic elements compared to Gandhara.", "Both the Gandhara and Mathura schools relied exclusively on red sandstone as their primary sculpting material."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Gandhara art reflects strong Greco-Roman influence, while Mathura art is considered more indigenous in style. Statement 3 is incorrect: the two schools used different materials -- Gandhara sculptures were typically carved from grey or bluish-grey schist, while Mathura sculptures characteristically used red sandstone, not both exclusively the same material.','ancient-gandhara-mathura-art-schools','original_pattern_matched','NCERT Fine Arts textbook -- chapter on Kushan-era art; Old NCERT, Ancient India (R. S. Sharma).','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements regarding the Sangam Age polity and economy:','{"statements": ["Alongside the three major Sangam dynasties (Chera, Chola and Pandya), several minor chieftaincies known as the ''Velir'' also existed across the Tamil region.", "The Sangam-age economy is understood to have relied significantly on trade with the Roman Empire, evidenced by finds of Roman gold coins at sites such as Arikamedu.", "Sangam texts indicate that a rigid, uniform four-fold varna system was universally practised across the entire Tamil region during this period."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: the Velir chieftaincies existed alongside the three crowned Sangam dynasties, and Indo-Roman trade is well attested by finds such as Roman coins at Arikamedu. Statement 3 is incorrect: Sangam society had its own distinct social classifications rather than a rigid, uniformly enforced four-fold varna order across the region, with Brahmanical influence being only partial and gradual.','ancient-sangam-polity-economy','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Sangam Age.','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements regarding Gupta-era trade and coinage:','{"statements": ["Gupta gold coins, known as ''dinaras'', depict rulers in various poses, including as archers, and are considered artistically sophisticated.", "Some historians point to a decline in long-distance trade and reduced gold coin circulation in the Later Gupta period as evidence of the empire''s weakening economy.", "There is unanimous consensus among historians that the decline in overseas trade during the Gupta period was caused entirely by a single factor -- the Huna invasions -- with no other contributing cause."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Gupta gold dinaras, including archer-type coins, are noted for their artistry, and historians do cite reduced trade and coin circulation as evidence of later Gupta economic decline. Statement 3 is incorrect: there is no such unanimous single-cause consensus -- historians debate multiple contributing factors, including Huna invasions, disruptions in Roman trade, and internal administrative changes, rather than attributing the decline to one factor alone.','ancient-gupta-trade-decline-debate','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Gupta economy and its decline.','draft'),
('upsc','History','Ancient','statement_based','hard','Consider the following statements regarding Harshavardhana''s religious patronage:','{"statements": ["Harshavardhana convened a religious assembly at Kannauj that is associated with honouring and propagating Mahayana Buddhist teachings.", "He also convened a quinquennial (once-in-five-years) assembly at Prayaga (Allahabad) for the distribution of charity.", "Harshavardhana''s court exclusively patronised Buddhism and extended no patronage to Brahmanical or Jain traditions."], "closing": "How many of the above statements are correct?"}'::jsonb,'[{"id": "a", "body": "Only one", "isCorrect": false}, {"id": "b", "body": "Only two", "isCorrect": true}, {"id": "c", "body": "All three", "isCorrect": false}, {"id": "d", "body": "None", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct: Harsha convened the Kannauj assembly associated with Mahayana Buddhism, and held the quinquennial Prayaga assembly for charitable distribution, both recorded by Xuanzang. Statement 3 is incorrect: Harsha''s patronage was eclectic, extending to Shaivism and other Brahmanical traditions as well as Buddhism -- reflected even in his own plays, which invoke Shaiva themes, alongside his Buddhist-associated assemblies.','ancient-harsha-religious-patronage','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on Harshavardhana.','draft'),
('upsc','History','Modern','mcq','easy','Who among the following is known as the ''Grand Old Man of India''?','{}'::jsonb,'[{"id": "a", "body": "Gopal Krishna Gokhale", "isCorrect": false}, {"id": "b", "body": "Dadabhai Naoroji", "isCorrect": true}, {"id": "c", "body": "Surendranath Banerjee", "isCorrect": false}, {"id": "d", "body": "Womesh Chandra Bonnerjee", "isCorrect": false}]'::jsonb,2,0.66,'Dadabhai Naoroji is known as the ''Grand Old Man of India'', a senior Moderate leader, author of ''Poverty and Un-British Rule in India'' (the Drain Theory), and the first Indian to become a member of the British House of Commons. Gokhale, Banerjee and Bonnerjee were all prominent contemporaries but are not associated with this particular title.','modern-dadabhai-naoroji-title','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on early nationalist leaders.','draft'),
('upsc','History','Modern','mcq','easy','In which year was the Quit India Movement launched?','{}'::jsonb,'[{"id": "a", "body": "1940", "isCorrect": false}, {"id": "b", "body": "1942", "isCorrect": true}, {"id": "c", "body": "1930", "isCorrect": false}, {"id": "d", "body": "1945", "isCorrect": false}]'::jsonb,2,0.66,'The Quit India Movement was launched in August 1942, following the failure of the Cripps Mission. 1940 marks the Individual Satyagraha, 1930 the launch of Civil Disobedience (Dandi March), and 1945 the Shimla Conference -- none of which is the Quit India launch year.','modern-quit-india-year','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the Quit India Movement.','draft'),
('upsc','History','Modern','mcq','easy','''Vande Mataram'', later adopted as India''s national song, was composed by which of the following?','{}'::jsonb,'[{"id": "a", "body": "Rabindranath Tagore", "isCorrect": false}, {"id": "b", "body": "Bankim Chandra Chatterjee", "isCorrect": true}, {"id": "c", "body": "Sarojini Naidu", "isCorrect": false}, {"id": "d", "body": "Muhammad Iqbal", "isCorrect": false}]'::jsonb,2,0.66,'''Vande Mataram'' was composed by Bankim Chandra Chatterjee, appearing in his 1882 novel Anandamath. Rabindranath Tagore notably set a portion of it to music and sang it at the 1896 Congress session, which is why he is often mistakenly credited as its composer, but authorship remains Bankim Chandra''s. Sarojini Naidu and Muhammad Iqbal are unrelated to the song''s composition.','modern-vande-mataram-authorship','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on cultural nationalism.','draft'),
('upsc','History','Modern','mcq','easy','Who was the first Governor-General of independent India (1947-48)?','{}'::jsonb,'[{"id": "a", "body": "C. Rajagopalachari", "isCorrect": false}, {"id": "b", "body": "Lord Wavell", "isCorrect": false}, {"id": "c", "body": "Lord Mountbatten", "isCorrect": true}, {"id": "d", "body": "Lord Linlithgow", "isCorrect": false}]'::jsonb,2,0.66,'Lord Mountbatten served as the first Governor-General of independent India, from August 1947 until June 1948. C. Rajagopalachari succeeded him and is instead correctly remembered as the first (and only) Indian-born Governor-General of India -- a common point of confusion with ''first Governor-General of independent India''. Wavell and Linlithgow were earlier Viceroys under British rule, before independence.','modern-first-governor-general-independent-india','original_pattern_matched','NCERT/Bipan Chandra, India''s Struggle for Independence -- chapter on the transfer of power.','draft'),
('upsc','History','Ancient','mcq','easy','Who founded the Mauryan Empire?','{}'::jsonb,'[{"id": "a", "body": "Ashoka", "isCorrect": false}, {"id": "b", "body": "Bindusara", "isCorrect": false}, {"id": "c", "body": "Chandragupta Maurya", "isCorrect": true}, {"id": "d", "body": "Chanakya", "isCorrect": false}]'::jsonb,2,0.66,'Chandragupta Maurya founded the Mauryan Empire around 321 BCE, guided by his mentor Chanakya (Kautilya). Bindusara and Ashoka were his son and grandson respectively, later rulers of the dynasty, while Chanakya was Chandragupta''s chief advisor and strategist, not the founder-emperor himself.','ancient-mauryan-empire-founder','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the rise of the Mauryan Empire.','draft'),
('upsc','History','Ancient','mcq','easy','Which of the following is the oldest of the four Vedas?','{}'::jsonb,'[{"id": "a", "body": "Sama Veda", "isCorrect": false}, {"id": "b", "body": "Yajur Veda", "isCorrect": false}, {"id": "c", "body": "Rig Veda", "isCorrect": true}, {"id": "d", "body": "Atharva Veda", "isCorrect": false}]'::jsonb,2,0.66,'The Rig Veda is the oldest of the four Vedas, primarily a collection of hymns. The Sama Veda, Yajur Veda and Atharva Veda were composed later, drawing in part on Rig Vedic material for liturgical and ritual purposes.','ancient-oldest-veda','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Vedic Period.','draft'),
('upsc','History','Ancient','mcq','easy','Which ancient Indian text, attributed to Kautilya, is a treatise on statecraft, economics and military strategy?','{}'::jsonb,'[{"id": "a", "body": "Manusmriti", "isCorrect": false}, {"id": "b", "body": "Mudrarakshasa", "isCorrect": false}, {"id": "c", "body": "Arthashastra", "isCorrect": true}, {"id": "d", "body": "Indica", "isCorrect": false}]'::jsonb,2,0.66,'The Arthashastra, attributed to Kautilya (Chanakya), is a treatise on statecraft, economic policy and military strategy. The Manusmriti is a separate text on law and social conduct; the Mudrarakshasa is a Sanskrit play by Vishakhadatta about Chandragupta Maurya''s rise to power, not a statecraft treatise itself; and the Indica is the account of the Greek ambassador Megasthenes, not an Indian text.','ancient-arthashastra-authorship','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the Mauryan Empire and Kautilya''s Arthashastra.','draft'),
('upsc','History','Ancient','mcq','easy','At which of the following places did Gautama Buddha deliver his first sermon after attaining enlightenment?','{}'::jsonb,'[{"id": "a", "body": "Bodh Gaya", "isCorrect": false}, {"id": "b", "body": "Kushinagar", "isCorrect": false}, {"id": "c", "body": "Sarnath", "isCorrect": true}, {"id": "d", "body": "Lumbini", "isCorrect": false}]'::jsonb,2,0.66,'The Buddha delivered his first sermon (the Dharmachakra Pravartana, ''turning of the wheel of law'') at Sarnath, near Varanasi. Bodh Gaya is where he attained enlightenment, Kushinagar is where he attained mahaparinirvana (death), and Lumbini is his birthplace -- each a genuine site associated with the Buddha''s life, but tied to a different event.','ancient-buddha-first-sermon-sarnath','original_pattern_matched','Old NCERT, Ancient India (R. S. Sharma) -- chapter on the life of the Buddha and Buddhist sites.','draft')
